import {categories,stays,transports,activities,defaultState,restoreState,generateItems} from './model.js';
import {listPhotos,importPhoto,removePhoto} from './photos.js';
const $=s=>document.querySelector(s), main=$('#main'),dialog=$('#dialog'),STORAGE='mala-pronta-web-v1';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=defaultState(),filter='all',activeTab='checklist',renderId=0,photoUrls=[],toastTimer,installPrompt,photoBusy=false;
const collapsed=new Set();
try{const saved=localStorage.getItem(STORAGE);if(saved)state=restoreState(JSON.parse(saved));}catch(error){storageProblem('Não foi possível recuperar o checklist. O navegador pode estar bloqueando o armazenamento local.');}
function storageProblem(message){$('#save-error').hidden=false;$('#save-error').textContent=message;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));$('#save-error').hidden=true;return true;}catch(error){storageProblem('Não foi possível salvar as alterações neste navegador. Libere espaço ou use uma aba normal antes de fechar o aplicativo.');return false;}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function image(name,alt,cls=''){return `<img src="./assets/${name}.png" alt="${escape(alt)}" class="${cls}" decoding="async">`;}
function title(eyebrow,heading,sub){return `<div class="page-title"><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p>${sub}</p></div>`;}
function openDialog(html,cls=''){if(dialog.open)dialog.close();dialog.returnValue='';dialog.className=cls;$('#dialog-content').innerHTML=html;dialog.showModal();}
function confirmAction(heading,message,button='Confirmar'){return new Promise(resolve=>{openDialog(`<h2>${escape(heading)}</h2><p>${escape(message)}</p><div class="actions"><button class="btn" id="cancel-action">Cancelar</button><button class="btn danger" id="confirm-action">${escape(button)}</button></div>`);$('#cancel-action').onclick=()=>dialog.close('no');$('#confirm-action').onclick=()=>dialog.close('yes');dialog.addEventListener('close',()=>resolve(dialog.returnValue==='yes'),{once:true});});}
function progress(){const all=generateItems(state),checked=new Set(state.checked);return {all,checked,done:all.filter(i=>checked.has(i.id)).length};}
function render(){renderId++;for(const url of photoUrls)URL.revokeObjectURL(url);photoUrls=[];
 activeTab=['checklist','viagem','documentos','dicas'].includes(location.hash.slice(1))?location.hash.slice(1):'checklist';
 document.querySelectorAll('[data-tab]').forEach(a=>{if(a.dataset.tab===activeTab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(activeTab==='checklist')renderChecklist();else if(activeTab==='viagem')renderTrip();else if(activeTab==='documentos')renderDocuments(renderId);else renderTips();
 document.title=`${{checklist:'Checklist',viagem:'Minha viagem',documentos:'Documentos',dicas:'Dicas'}[activeTab]} • Mala Pronta`;
}
function renderChecklist(){const {all,done}=progress(),t=state.trip,percent=Math.round(done*100/all.length);
 main.innerHTML=`${image('inter_2026','Inter Prudente 2026','event-logo')}<div class="welcome"><h1>Bora fazer a mala?</h1>${image('mascot_travel','Chaminha com a mochila pronta para viajar')}</div>
 <section class="hero" aria-label="Progresso da mala"><button class="trip-link" id="edit-trip">${escape(state.name)} &nbsp; ↗</button><strong id="progress-count">${done} / ${all.length} itens</strong><p id="progress-sub">${done===all.length?'Mala pronta. Agora é só aproveitar!':`Seu checklist • ${percent}% pronto`}</p><div class="progress-track" role="progressbar" aria-label="Mala pronta" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><div id="progress-fill" style="width:${percent}%"></div></div></section>
 ${t.personalized?`<p class="trip-summary">${t.days} dias • ${escape(stays[t.stay])} • lista personalizada</p>`:''}
 <div class="filters" role="group" aria-label="Filtrar checklist">${[['all','Todos'],['pending','Pendentes'],['packed','Na mala']].map(([value,label])=>`<button data-filter="${value}" aria-pressed="${filter===value}">${label}</button>`).join('')}</div>
 <div class="categories" id="categories"></div><button class="btn full" id="add-item">+ Adicionar item à mala</button><p class="small-note">Salvo automaticamente neste aparelho. Cada pessoa tem seu próprio checklist.</p><div class="actions"><button class="btn" id="share">Compartilhar lista</button><button class="btn" id="reset">Limpar marcações</button></div>`;
 $('#edit-trip').onclick=()=>location.hash='viagem';document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderChecklist();});$('#add-item').onclick=addCustom;$('#share').onclick=shareList;$('#reset').onclick=async()=>{if(await confirmAction('Começar a mala de novo?','Todas as marcações serão desfeitas. Sua viagem, seus itens extras e suas fotos serão mantidos.','Limpar marcações')){state.checked=[];save();renderChecklist();toast('Marcações limpas. Bora preparar a próxima mala!');}};renderCategories();
}
function renderCategories(){const {all,checked}=progress();let visibleCount=0;
 const icons=['▣','♧','✦','+','ϟ','☾','♫','☆'];
 $('#categories').innerHTML=categories.map((name,c)=>{const total=all.filter(i=>i.category===c),done=total.filter(i=>checked.has(i.id)).length,group=total.filter(i=>filter==='all'||(filter==='pending'&&!checked.has(i.id))||(filter==='packed'&&checked.has(i.id)));if(!group.length)return '';visibleCount+=group.length;
 return `<details class="category" data-category="${c}" ${collapsed.has(c)?'':'open'}><summary><span class="category-icon" aria-hidden="true">${icons[c]}</span><span class="category-title">${name}</span><span class="counter" id="counter-${c}">${done}/${total.length}</span></summary>${group.map(i=>`<div class="check-row"><label class="check-label"><input type="checkbox" data-item="${escape(i.id)}" ${checked.has(i.id)?'checked':''}><span>${escape(i.label)}</span></label>${i.id.startsWith('custom-')?`<button class="remove-custom" data-remove="${escape(i.id)}" aria-label="Excluir ${escape(i.label)}">×</button>`:''}</div>`).join('')}</details>`;
 }).join('');
 if(!visibleCount)$('#categories').innerHTML=`<div class="empty-filter">${filter==='pending'?'Tudo na mala! ✓':'Nenhum item marcado ainda.'}</div>`;
 document.querySelectorAll('[data-category]').forEach(el=>el.addEventListener('toggle',()=>{const c=Number(el.dataset.category);if(el.open)collapsed.delete(c);else collapsed.add(c);}));
 document.querySelectorAll('[data-item]').forEach(input=>input.onchange=()=>{const checked=new Set(state.checked);if(input.checked)checked.add(input.dataset.item);else checked.delete(input.dataset.item);state.checked=[...checked];save();updateProgress();if(filter!=='all')renderCategories();});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{const item=state.custom.find(i=>i.id===b.dataset.remove);if(item&&await confirmAction('Excluir item extra?',item.label,'Excluir')){state.custom=state.custom.filter(i=>i.id!==item.id);state.checked=state.checked.filter(id=>id!==item.id);save();renderChecklist();}});
}
function updateProgress(){const {all,checked,done}=progress(),percent=Math.round(done*100/all.length);$('#progress-count').textContent=`${done} / ${all.length} itens`;$('#progress-sub').textContent=done===all.length?'Mala pronta. Agora é só aproveitar!':`Seu checklist • ${percent}% pronto`;$('#progress-fill').style.width=`${percent}%`;$('.progress-track').setAttribute('aria-valuenow',percent);categories.forEach((_,c)=>{const counter=$(`#counter-${c}`),group=all.filter(i=>i.category===c);if(counter)counter.textContent=`${group.filter(i=>checked.has(i.id)).length}/${group.length}`;});}
function addCustom(){openDialog(`<h2>O que mais vai na mala?</h2><p>Seu item aparecerá em Extras que salvam.</p><form id="custom-form"><label>Nome do item<input class="text-input" name="label" placeholder="Ex.: bandeira da atlética" maxlength="120" required autofocus></label><div class="actions"><button class="btn" type="button" id="cancel-custom">Cancelar</button><button class="btn primary" type="submit">Adicionar</button></div></form>`);$('#custom-form').elements.label.oninput=e=>e.target.setCustomValidity('');$('#cancel-custom').onclick=()=>dialog.close();$('#custom-form').onsubmit=e=>{e.preventDefault();const label=e.target.elements.label.value.trim();if(!label){e.target.elements.label.setCustomValidity('Digite o nome do item.');e.target.reportValidity();return;}state.custom.push({id:`custom-${crypto.randomUUID()}`,label,category:7});filter='all';collapsed.delete(7);save();dialog.close();renderChecklist();toast('Item adicionado em Extras que salvam.');};}
async function shareList(){const {all,checked}=progress();let text=`🎒 ${state.name}\n\n`;categories.forEach((name,c)=>{text+=`${name}\n`;all.filter(i=>i.category===c).forEach(i=>text+=`${checked.has(i.id)?'[x]':'[ ]'} ${i.label}\n`);text+='\n';});try{if(navigator.share){await navigator.share({title:'Mala Pronta',text});}else{await navigator.clipboard.writeText(text);toast('Lista copiada! Agora é só colar e compartilhar.');}}catch(e){if(e.name!=='AbortError'){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='minha-mala.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Lista exportada como arquivo de texto.');}}}
function options(values,selected){return values.map((s,i)=>`<option value="${i}" ${i===selected?'selected':''}>${s}</option>`).join('');}
function renderTrip(){const t=state.trip;
 main.innerHTML=title('DO SEU JEITO','Qual é o próximo rolê?','Adapte sua mala para o Inter, TUSCA, jogos ou uma excursão da atlética.')+` <form class="trip-form" id="trip-form"><label>Nome da viagem<input name="name" maxlength="60" value="${escape(state.name)}" required></label><div class="form-grid"><label>Duração<select name="duration">${options(['2 a 3 dias','4 a 5 dias','6 a 7 dias','Mais de uma semana'],t.days<=3?0:t.days<=5?1:t.days<=7?2:3)}</select></label><label>Quantidade exata de dias<input name="days" type="number" inputmode="numeric" min="1" max="60" step="1" required value="${t.days}"></label><label>Hospedagem<select name="stay">${options(stays,t.stay)}</select></label><label>Transporte<select name="transport">${options(transports,t.transport)}</select></label></div><label>O que pretende fazer?<select name="activity">${options(activities,t.activity)}</select></label>
 <div class="info-card"><strong>Uma mala com a sua cara</strong><p>Sugerimos camisetas por dia e 2 extras de roupas íntimas e meias. Hotel oculta 5 itens de cama: confirme o que a hospedagem oferece. Camping, praia, competição e transporte podem acrescentar itens.</p></div><button class="btn primary full" type="submit">Personalizar meu checklist →</button></form>
 ${t.personalized?'<button class="btn full" id="original">Usar lista original de 78 itens</button>':''}<p class="small-note">A versão web tem armazenamento próprio. Os dados do APK não são transferidos automaticamente.</p>${sportsGallery()}`;
 const form=$('#trip-form');form.elements.duration.onchange=()=>{form.elements.days.value=[3,5,7,10][Number(form.elements.duration.value)];};form.onsubmit=e=>{e.preventDefault();const fields=form.elements,name=fields.name.value.trim(),days=Number(fields.days.value);if(!name||!Number.isInteger(days)||days<1||days>60){toast('Preencha um nome e uma duração de 1 a 60 dias.');return;}state.name=name;state.trip={days,stay:Number(fields.stay.value),transport:Number(fields.transport.value),activity:Number(fields.activity.value),personalized:true};save();filter='all';location.hash='checklist';toast('Checklist adaptado! Suas marcações foram mantidas.');};
 if($('#original'))$('#original').onclick=async()=>{if(await confirmAction('Restaurar a lista original?','A personalização será desativada. As marcações, os itens extras e as fotos serão preservados.','Restaurar')){state.trip.personalized=false;save();filter='all';location.hash='checklist';}};
}
function sportsGallery(){const sports=[['atletismo','Atletismo'],['basquete','Basquete'],['futsal_futebol','Futebol / futsal'],['handebol','Handebol'],['lutas','Lutas'],['tenisdecampo','Tênis de campo'],['tenisdemesa','Tênis de mesa'],['volei','Vôlei']];return `<section class="sport-section"><h2>No clima dos jogos</h2><p>Os mascotes das modalidades também estão na viagem.</p><div class="sport-strip" tabindex="0" aria-label="Mascotes esportivos, deslize para ver mais">${sports.map(([file,name])=>`<div class="sport-card">${image(`sport_${file}`,`Mascote de ${name}`)}<span>${name}</span></div>`).join('')}</div></section>`;}
async function renderDocuments(id){main.innerHTML=title('TUDO À MÃO','Seus documentos','Fotos de RG, CNH e ingressos para consultar mesmo sem internet.')+`<button class="btn primary full" id="add-photo" ${photoBusy?'disabled':''}>${photoBusy?'Guardando imagem…':'+ Guardar uma foto'}</button><div class="info-card"><strong>Guardadas só neste aparelho</strong><p>As fotos não são enviadas ao site. Elas ficam neste navegador ou aplicativo instalado. Limpar os dados do site ou do navegador pode apagá-las; o sistema também pode liberar esse espaço. Mantenha os originais e seu documento físico.</p></div><div id="photos"><p class="loading">Abrindo sua pasta…</p></div>`;$('#add-photo').onclick=photoName;
 try{const photos=await listPhotos();if(id!==renderId||activeTab!=='documentos')return;
 $('#photos').innerHTML=`<p class="photo-count">${photos.length} ${photos.length===1?'foto guardada':'fotos guardadas'}</p>`+(photos.length?`<div class="photo-grid">${photos.map(photo=>{const url=URL.createObjectURL(photo.thumb||photo.blob);photoUrls.push(url);return `<article class="photo-card"><div class="photo-meta"><img src="${url}" alt="Miniatura de ${escape(photo.title)}" class="photo-thumb"><div><h2>${escape(photo.title)}</h2><p>${formatSize(photo.size)} • disponível offline</p></div></div><div class="actions"><button class="btn" data-open-photo="${photo.id}">Abrir foto</button><button class="btn" data-delete-photo="${photo.id}" aria-label="Excluir ${escape(photo.title)}">Excluir</button></div></article>`;}).join('')}</div>`:`<div class="empty-card"><div><h2>Sua pasta de viagem</h2><p>Guarde frente e verso do documento ou uma imagem de cada ingresso. Dê um nome para encontrar tudo com facilidade.</p></div>${image('mascot_phone','Chaminha com celular')}</div>`);
 document.querySelectorAll('[data-open-photo]').forEach(b=>b.onclick=()=>viewPhoto(photos.find(p=>p.id===b.dataset.openPhoto)));document.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=async()=>{const photo=photos.find(p=>p.id===b.dataset.deletePhoto);if(await confirmAction('Excluir esta foto?',`${photo.title} será removida deste app. A imagem original da sua galeria será mantida.`,'Excluir')){try{await removePhoto(photo.id);render();toast('Foto excluída deste aparelho.');}catch(e){toast('Não foi possível excluir a foto. Tente novamente.');}}});
 }catch(e){if(id!==renderId)return;$('#photos').innerHTML=`<div class="empty-card"><p>Não foi possível abrir o armazenamento de fotos. Use uma aba normal, confira o espaço disponível e tente novamente.</p></div>`;}
}
function formatSize(bytes){return bytes<1024*1024?`${Math.max(1,Math.round(bytes/1024))} KB`:`${(bytes/1024/1024).toLocaleString('pt-BR',{maximumFractionDigits:1})} MB`;}
function photoName(){openDialog(`<h2>Nome da foto</h2><p>Escolha depois uma imagem da galeria ou dos arquivos. Até 25 MB por foto.</p><form id="photo-name-form"><label>Nome<input class="text-input" name="title" maxlength="80" placeholder="Ex.: RG — frente ou Ingresso Inter" required autofocus></label><div class="actions"><button class="btn" type="button" id="cancel-photo">Cancelar</button><button class="btn primary" type="submit">Escolher imagem</button></div></form>`);$('#photo-name-form').elements.title.oninput=e=>e.target.setCustomValidity('');$('#cancel-photo').onclick=()=>dialog.close();$('#photo-name-form').onsubmit=e=>{e.preventDefault();const title=e.target.elements.title.value.trim();if(!title){e.target.elements.title.setCustomValidity('Dê um nome à foto.');e.target.reportValidity();return;}
 const input=document.createElement('input');input.type='file';input.accept='image/*';input.className='file-picker';$('#dialog-content').append(input);input.oncancel=()=>input.remove();input.onchange=async()=>{const file=input.files?.[0];input.remove();if(!file)return;dialog.close();photoBusy=true;render();try{await importPhoto(file,title);toast('Foto guardada para consultar offline.');if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}catch(error){toast(error.name==='QuotaExceededError'?'Sem espaço para guardar a foto. Libere armazenamento e tente novamente.':error.message||'Não foi possível guardar a foto.');}finally{photoBusy=false;if(activeTab==='documentos')render();}};input.click();};}
function viewPhoto(photo){const url=URL.createObjectURL(photo.blob);openDialog(`<div class="viewer-header"><button class="btn" id="close-viewer">← Voltar</button><h2>${escape(photo.title)}</h2></div><p class="viewer-note">Use dois dedos para ampliar e arraste para mover.</p><div class="photo-stage" id="photo-stage"><img src="${url}" id="full-photo" alt="${escape(photo.title)}" draggable="false"></div><div class="zoom-controls"><button id="zoom-out" aria-label="Diminuir foto">−</button><button class="fit" id="zoom-fit">Ajustar à tela</button><button id="zoom-in" aria-label="Ampliar foto">+</button></div>`,'viewer');
 let zoom=1,x=0,y=0,distance=0;const pointers=new Map(),img=$('#full-photo'),stage=$('#photo-stage');const draw=()=>{img.style.transform=`translate(${x}px,${y}px) scale(${zoom})`;};const setZoom=value=>{zoom=Math.max(1,Math.min(8,value));if(zoom===1)x=y=0;draw();};$('#close-viewer').onclick=()=>dialog.close();$('#zoom-out').onclick=()=>setZoom(zoom/1.5);$('#zoom-in').onclick=()=>setZoom(zoom*1.5);$('#zoom-fit').onclick=()=>{zoom=1;x=y=0;draw();};
 stage.onpointerdown=e=>{stage.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});distance=0;};stage.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const prior=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()];const d=Math.hypot(a.x-b.x,a.y-b.y);if(distance)setZoom(zoom*d/distance);distance=d;}else if(zoom>1){x+=e.clientX-prior.x;y+=e.clientY-prior.y;draw();}};stage.onpointerup=stage.onpointercancel=e=>{pointers.delete(e.pointerId);distance=0;};stage.onwheel=e=>{e.preventDefault();setZoom(zoom*(e.deltaY<0?1.1:.9));};dialog.addEventListener('close',()=>{img.src='';URL.revokeObjectURL(url);},{once:true});
}
const tips=[['Dois tênis, menos perrengue','Leve um que possa sujar ou molhar e outro confortável para o dia a dia.'],['Uma troca sempre por perto','Separe uma troca de roupa na mochila para o trajeto. Leve roupas íntimas extras.'],['Seu nome em tudo','Identifique carregadores, toalhas e malas. Uma etiqueta pode salvar o dia.'],['O essencial vai com você','Pochete ou shoulder bag facilita guardar celular, documento e dinheiro nas festas.'],['Cada um com seu kit','Leve seus próprios itens de higiene e deixe o que mais usa em uma nécessaire fácil de alcançar.'],['Água também faz parte do rolê','Cuide da hidratação em festas longas e no calor, especialmente se consumir álcool. Não misture álcool com medicamentos ou outras substâncias.'],['Confira antes de sair','Confirme roupa de cama, regras da hospedagem e previsão do tempo. Quantidades são sugestões: ajuste ao seu uso e à possibilidade de lavar roupas.']];
function renderTips(){main.innerHTML=title('PRA CURTIR SEM PERRENGUE','O rolê passa.<br>As histórias ficam.','Alguns lembretes para o Inter e qualquer outra viagem universitária.')+`<div class="cheer-card">${image('mascot_thumb','Chaminha fazendo sinal de positivo')}<strong>Cuide de você e curta o rolê!</strong></div>`+tips.map(([heading,text],i)=>`<article class="tip-card"><h2><span>${String(i+1).padStart(2,'0')} /</span>${heading}</h2><p>${text}</p></article>`).join('')+`<button class="btn full" id="install-help">Como instalar no celular</button><p class="small-note">Mala Pronta • versão web 1.0<br>Sem conta. Checklist e fotos guardados neste aparelho.<br>Abra online uma primeira vez e aguarde a indicação “Offline pronto” antes de viajar.</p>`;$('#install-help').onclick=installHelp;}
function installHelp(){const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;if(standalone){toast('Você já está usando o aplicativo instalado.');return;}
 if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>{installPrompt=null;});return;}
 openDialog(`<h2>Leve a mala pra tela inicial</h2><p><strong>No iPhone ou iPad</strong></p><ol><li>Abra este link no <strong>Safari</strong>.</li><li>Toque em <strong>Compartilhar</strong>.</li><li>Escolha <strong>Adicionar à Tela de Início</strong> e confirme. Se aparecer, ative “Abrir como App da Web”.</li></ol><p><strong>No Android</strong></p><p>Abra no Chrome e use o menu <strong>Instalar aplicativo</strong> ou <strong>Adicionar à tela inicial</strong>.</p><p>Depois da primeira abertura online, aguarde “Offline pronto”. As fotos e marcações são próprias de cada aparelho.</p><button class="btn primary full" id="close-install">Entendi</button>`);$('#close-install').onclick=()=>dialog.close();}
$('#install').onclick=installHelp;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('appinstalled',()=>{installPrompt=null;$('#install').textContent='Instalado ✓';toast('Mala Pronta na tela inicial!');});
let offlineReady=false;function connection(){const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;$('#connection').textContent=!navigator.onLine?(offlineReady?'Você está offline • tudo por aqui':'Você está offline'):offlineReady?'Offline pronto • salvo no aparelho':'Sua mala • preparando offline';if(standalone)$('#install').textContent='Instalado ✓';}
window.addEventListener('online',connection);window.addEventListener('offline',connection);window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue){try{state=restoreState(JSON.parse(e.newValue));render();}catch{}}});
render();connection();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;connection();}).catch(()=>{$('#connection').textContent='Online • offline indisponível';});}else $('#connection').textContent='Salvo neste aparelho';
